import React from 'react';
import { motion } from 'framer-motion';
import {
  Key,
  Shuffle,
  FileLock,
  UploadCloud,
  CheckCircle,
  Lock
} from 'lucide-react';

const CryptoFlow = ({ currentStep }) => {

  const steps = [
    {
      id: 1,
      label: "Ephemeral Agreement",
      sub: "X25519",
      icon: Key,
      branches: ["Generate ephemeral key", "Exchange public values"]
    },
    {
      id: 2,
      label: "Encapsulate Secret",
      sub: "Shared Secret",
      icon: FileLock,
      branches: ["Compute secret", "Create ciphertext"]
    },
    {
      id: 3,
      label: "HKDF Derivation",
      sub: "SHA-256",
      icon: Shuffle,
      branches: ["Mix salt", "Expand to AES key"]
    },
    {
      id: 4,
      label: "Encrypt Payload",
      sub: "AES-256-GCM",
      icon: Lock,
      branches: ["Encrypt blocks", "Generate tag"]
    },
    {
      id: 5,
      label: "Upload to Cloud",
      sub: "Untrusted",
      icon: UploadCloud,
      branches: ["Pack blob", "Push storage"]
    },
  ];

  return (
    <div className="bg-black/40 p-6 rounded-lg border border-scifi-border mb-6">
      <div className="flex justify-between items-center relative">

        {/* base line */}
        <div className="absolute top-1/2 left-0 w-full h-1 bg-gray-800 -z-0"></div>

        {/* active progress */}
        <div
          className="absolute top-1/2 left-0 h-1 bg-neon-green transition-all duration-700 -z-0"
          style={{
            width: `${((currentStep - 1) / (steps.length - 1)) * 100}%`
          }}
        />

        {steps.map((step, index) => {
          const isActive = currentStep >= index + 1;
          const isCurrent = currentStep === index + 1;
          const Icon = step.icon;

          return (
            <div key={step.id} className="relative z-10 flex flex-col items-center w-32">

              {/* circle */}
              <motion.div
                initial={{ scale: 0.8 }}
                animate={{ scale: isActive ? 1.1 : 1 }}
                className={`w-12 h-12 rounded-full flex items-center justify-center border-2 bg-scifi-bg
                  ${isActive
                    ? 'text-neon-green border-neon-green shadow-[0_0_15px_rgba(0,255,157,0.4)]'
                    : 'border-gray-700 text-gray-700'
                  }`}
              >
                {isActive && !isCurrent
                  ? <CheckCircle size={20} />
                  : <Icon size={20} />}
              </motion.div>

              {/* title */}
              <div className="mt-3 text-center">
                <p className={`text-[10px] font-bold uppercase ${isActive ? 'text-white' : 'text-gray-600'}`}>
                  {step.label}
                </p>
                <p className="text-[9px] text-gray-500 font-mono">{step.sub}</p>
              </div>

              {/* branches */}
              <div className="mt-2 relative">
                {step.branches.map((b, i) => (
                  <div
                    key={i}
                    className={`text-[9px] font-mono whitespace-nowrap
                      ${index % 2 === 0 ? "translate-y-4" : "-translate-y-4"}
                      ${isActive ? "text-neon-green" : "text-gray-600"}`}
                  >
                    {b}
                  </div>
                ))}
              </div>

            </div>
          );
        })}
      </div>
    </div>
  );
};

export default CryptoFlow;
